public interface IOrderRepository
{
    Task<Order?> FindAsync(Guid id, CancellationToken ct);
    Task SaveAsync(Order order, CancellationToken ct);
}

public sealed class PayOrderHandler(IOrderRepository repository)
{
    public async Task Handle(Guid id, CancellationToken ct)
    {
        var order = await repository.FindAsync(id, ct) ?? throw new InvalidOperationException();
        order.Pay();
        await repository.SaveAsync(order, ct);
    }
}
